actions.script:
import org.moqui.context.ExecutionContext
import org.moqui.entity.EntityCondition
ExecutionContext ec = context.ec
Calendar basisCal = ec.user.getCalendarSafe()
basisCal.add(Calendar.DAY_OF_YEAR, (int) -daysToKeep)
basisTimestamp = new Timestamp(basisCal.getTimeInMillis())
// Delete children of old conversations first so the LlmMessage FK cannot fail the job.
def oldConvs = ec.entity.find("moqui.llm.LlmConversation")
        .condition("lastMessageDate", EntityCondition.LESS_THAN, basisTimestamp)
        .disableAuthz().list()
def oldIds = oldConvs.collect { it.conversationId }.findAll { it }
// the searchable copy of content goes with the content
def deleteContentProjection = { List itemIds ->
    if (!itemIds) return
    def contentIds = ec.entity.find("moqui.llm.LlmContent").condition("llmItemId", EntityCondition.IN, itemIds)
            .selectField("llmContentId").disableAuthz().list()*.llmContentId
    if (contentIds) ec.entity.find("moqui.llm.LlmContextProjection").condition("sourceType", "content")
            .condition("sourceId", EntityCondition.IN, contentIds).disableAuthz().deleteAll()
}
def terminalStatuses = ["LlmRunComplete", "LlmRunFailed", "LlmRunCancelled"]
def activeRuns = ec.entity.find("moqui.llm.LlmRun")
        .condition("statusId", EntityCondition.NOT_IN, terminalStatuses).disableAuthz().list()
def activeConversationIds = activeRuns.collect { it.conversationId }.findAll { it } as Set
oldIds.removeAll(activeConversationIds)
def oldTerminalRuns = ec.entity.find("moqui.llm.LlmRun")
        .condition("statusId", EntityCondition.IN, terminalStatuses)
        .condition("completedDate", EntityCondition.LESS_THAN, basisTimestamp).disableAuthz().list()
def oldTerminalRunIds = oldTerminalRuns.collect { it.runId }.findAll { it }
callLogsRemoved = 0L
messagesRemoved = 0L
conversationsRemoved = 0L
runsRemoved = 0L
// One conversation at a time, with its row locked and the decision made again with what is true now: a
// conversation that was picked up again after the list above was read is left alone, and only what is older
// than the limit is removed, so nothing a run wrote since can go.
for (String convId : oldIds) {
    // the same procedure the owner's delete uses, limited to what is older than the cutoff
    Map purged = org.moqui.impl.llm.LlmConversationPurge.purgeOlderThan(ec, convId, basisTimestamp)
    callLogsRemoved += (purged.callLogs ?: 0L) as long
    messagesRemoved += (purged.messages ?: 0L) as long
    if (purged.conversationRemoved) conversationsRemoved++
}
// a conversation that goes on keeps the run it continues from, so it can continue
def continuedFrom = ec.entity.find("moqui.llm.LlmConversation").condition("headRunId", EntityCondition.IN, oldTerminalRunIds ?: ["-"])
        .useCache(false).disableAuthz().list().collect { it.headRunId } as Set
oldTerminalRunIds = oldTerminalRunIds.findAll { !continuedFrom.contains(it) }
messagesRemoved += ec.entity.find("moqui.llm.LlmMessage")
        .condition("sentDate", EntityCondition.LESS_THAN, basisTimestamp)
        .disableAuthz().deleteAll()
def oldStandaloneResponses = ec.entity.find("moqui.llm.LlmResponse")
        .condition("createdDate", EntityCondition.LESS_THAN, basisTimestamp)
        .disableAuthz().list().findAll { !it.runId || oldTerminalRunIds.contains(it.runId) }
def oldStandaloneResponseIds = oldStandaloneResponses.collect { it.llmResponseId }.findAll { it }
if (oldStandaloneResponseIds) {
    def oldItems = ec.entity.find("moqui.llm.LlmItem")
            .condition("llmResponseId", EntityCondition.IN, oldStandaloneResponseIds)
            .disableAuthz().list()
    def oldItemIds = oldItems.collect { it.llmItemId }.findAll { it }
    if (oldItemIds) ec.entity.find("moqui.llm.LlmItem")
            .condition("sourceLlmItemId", EntityCondition.IN, oldItemIds)
            .disableAuthz().updateAll([sourceLlmItemId: null])
    ec.entity.find("moqui.llm.LlmResponseEvent")
            .condition("llmResponseId", EntityCondition.IN, oldStandaloneResponseIds)
            .disableAuthz().deleteAll()
    deleteContentProjection(oldItemIds)
        if (oldItemIds) ec.entity.find("moqui.llm.LlmContent")
            .condition("llmItemId", EntityCondition.IN, oldItemIds).disableAuthz().deleteAll()
    ec.entity.find("moqui.llm.LlmItem")
            .condition("llmResponseId", EntityCondition.IN, oldStandaloneResponseIds)
            .disableAuthz().deleteAll()
    ec.entity.find("moqui.llm.LlmResponse")
            .condition("llmResponseId", EntityCondition.IN, oldStandaloneResponseIds)
            .disableAuthz().deleteAll()
}
def oldStandaloneRequests = ec.entity.find("moqui.llm.LlmRequest")
        .condition("createdDate", EntityCondition.LESS_THAN, basisTimestamp)
        .disableAuthz().list().findAll { !it.runId || oldTerminalRunIds.contains(it.runId) }
def oldStandaloneRequestIds = oldStandaloneRequests.collect { it.llmRequestId }.findAll { it }
if (oldStandaloneRequestIds) {
    def oldItems = ec.entity.find("moqui.llm.LlmItem")
            .condition("llmRequestId", EntityCondition.IN, oldStandaloneRequestIds)
            .disableAuthz().list()
    def oldItemIds = oldItems.collect { it.llmItemId }.findAll { it }
    deleteContentProjection(oldItemIds)
        if (oldItemIds) ec.entity.find("moqui.llm.LlmContent")
            .condition("llmItemId", EntityCondition.IN, oldItemIds).disableAuthz().deleteAll()
    ec.entity.find("moqui.llm.LlmItem")
            .condition("llmRequestId", EntityCondition.IN, oldStandaloneRequestIds)
            .disableAuthz().deleteAll()
    ec.entity.find("moqui.llm.LlmRequest")
            .condition("llmRequestId", EntityCondition.IN, oldStandaloneRequestIds)
            .disableAuthz().deleteAll()
}
if (oldTerminalRunIds) {
    ec.entity.find("moqui.llm.LlmContextProjection")
            .condition("runId", EntityCondition.IN, oldTerminalRunIds).disableAuthz().deleteAll()
    ec.entity.find("moqui.llm.LlmToolInvocation")
            .condition("runId", EntityCondition.IN, oldTerminalRunIds).disableAuthz().deleteAll()
    ec.entity.find("moqui.llm.LlmRunStatus")
            .condition("runId", EntityCondition.IN, oldTerminalRunIds).disableAuthz().deleteAll()
    runsRemoved += ec.entity.find("moqui.llm.LlmRun")
            .condition("runId", EntityCondition.IN, oldTerminalRunIds).disableAuthz().deleteAll()
}
callLogsRemoved += ec.entity.find("moqui.llm.LlmCallLog")
        .condition("startDate", EntityCondition.LESS_THAN, basisTimestamp)
        .disableAuthz().deleteAll()
ec.logger.info("Removed ${callLogsRemoved} LlmCallLog, ${messagesRemoved} LlmMessage, ${conversationsRemoved} LlmConversation and ${runsRemoved} LlmRun records more than ${daysToKeep} days old")

def result = org.moqui.impl.llm.LlmRunStore.completeToolAndCheckpoint(ec, toolInvocationId,
        fencingToken, toolResult, success, contextItems, checkpoint)
context.putAll(result)

def result = org.moqui.impl.llm.LlmGateway.cancel(ec, conversationId)
if (result) context.putAll(result)
if (result?.httpStatus == 409)
    throw new org.moqui.llm.LlmException(result.message ?: "Conversation is not Streaming or Yielded",
            null, org.moqui.llm.LlmFinishReason.ERROR, 409, null, conversationId)
